// Mỗi nét: path SVG trên khung 320 x 180, màu tô, màu viền (0 = không), độ dày viền.

class ArtEl(val d: String, val fill: Long, val stroke: Long, val width: Float)

private fun e(d: String, fill: Long, stroke: Long, width: Float) = ArtEl(d, fill, stroke, width)

